// Differential/replay runner. Private tape generated by oracle.py on the MBP.
import {createReadStream,readFileSync,writeFileSync} from 'node:fs'
import {createInterface} from 'node:readline'
import {watch} from '../../core/watch.ts'
import {worker,lease,device,phases} from './port.ts'
import {bendLaws,extras,modelCase} from './laws.ts'
const wr=worker().rule,lr=lease(),dr=device()
const rules:any={worker:wr,observed:wr,real:wr,lease:lr,device:dr}
const runtimes=new Map<any,any>()
for(const r of [wr,lr,dr])runtimes.set(r,{compiled:r.compiled(),interpreted:r.interpreter()})
function mismatchOf(expected:any,actual:any,compiled:any){return !eq(actual,expected)||!eq(actual,compiled)}
const eq=(a:any,b:any)=>JSON.stringify(a)===JSON.stringify(b)
function wobs(s:any){
 const v=wr.decode(s),phase=v.phase
 if(['Running','Stalled'].includes(phase))return {phase,h:v.h,hb:v.hb,bg:v.bg}
 if(['Interrupted','Overdue'].includes(phase))return {phase,at:v.at,bg:v.bg}
 if(phase==='Completed')return {phase,bg:v.bg}
 if(phase==='Resumed')return {phase,by:v.by,bg:v.bg}
 return {phase}
}
function initial(params:any,value:any){
 const p=wr.encodeParams(params),s=wr.interpreter().init(p)
 const {phase,h,hb,at,bg,by}=value
 return {...s,scalars:{...s.scalars,phase:phases.indexOf(phase),h:h??0,hb:hb??0,at:at??0,bg:bg??0,by:by??0}}
}
const lawCases=[...bendLaws,...extras].map(e=>({entry:e,...modelCase(e.law_id)})).filter(c=>c.kind==='rule'&&c.rule.machine.name==='worker supervision')
const watchedLaws=lawCases.flatMap(c=>[...c.laws,...c.steps])
const counts:any={},divergences:any[]=[],real:any[]=[],watchedViolations:any[]=[]
let comparisonSteps=0,watchSteps=0
function observe(kind:string,r:any,s:any,input:any){
 if(['worker','observed','real'].includes(kind))return wobs(s)
 const v=r.decode(s)
 if(kind==='lease')return {holder:v.held?v.owner:null}
 return {holder:v.held?v.owner:null,fg:v.seen?v.fg:null,effect:v.installed?['Installed',input.a]:v.typed?['Typed',input.a,input.app]:['NoEff']}
}
for await(const line of createInterface({input:createReadStream('out/oracle.jsonl'),crlfDelay:Infinity})){
 const t=JSON.parse(line),r=rules[t.kind],runtime=runtimes.get(r),params=r.encodeParams(t.params??{})
 let s=t.initial?initial(t.params,t.initial):runtime.interpreted.init(params),g={...s,scalars:{...s.scalars},maps:{...s.maps}}
 const watches=t.kind==='real'?watchedLaws.map(law=>({name:law.name,on:watch(r.machine,runtime.interpreted,law,params,4)})):[]
 for(const w of watches)if(!w.on.start(s))watchedViolations.push({snapshot:t.snapshot,id:t.id,law:w.name,step:'start'})
 counts[t.kind]=(counts[t.kind]??0)+1
 let mismatch=false
 for(const [i,frame] of t.steps.entries()){
  const input=r.encodeInput(frame.input),before=s
  s=runtime.interpreted.step(params,s,input);g=runtime.compiled.step(params,g,input);comparisonSteps++
  const a=observe(t.kind,r,s,frame.input),b=observe(t.kind,r,g,frame.input)
  if(mismatchOf(frame.expected,a,b)&&!mismatch){
   divergences.push({kind:t.kind,id:t.id,snapshot:t.snapshot,step:i,input:frame.input,expected:frame.expected,actual:a,compiled:b,classification:!eq(a,b)?'generic kernel bug':'adapter bug'});mismatch=true
  }
  for(const w of watches){watchSteps++;if(!w.on.step(before,input,s))watchedViolations.push({snapshot:t.snapshot,id:t.id,law:w.name,step:i,input:frame.input})}
 }
 if(t.kind==='real')real.push({snapshot:t.snapshot,id:t.id,record:t.record,params:t.params,final:s,phase:wobs(s).phase,steps:t.steps.length})
}
// Fail-closed sabotage test. This belongs to the test-owned observer only, never production.
const sabotageParams=wr.encodeParams({lim:0,heavy:false,exc:0}),sabotageInput=wr.encodeInput({event:'Interrupt',host:0,t:0,successor:0,log:false})
const sabotageRuntime=runtimes.get(wr),sabotageActual=wobs(sabotageRuntime.interpreted.step(sabotageParams,sabotageRuntime.interpreted.init(sabotageParams),sabotageInput))
const sabotageCompiled=wobs(sabotageRuntime.compiled.step(sabotageParams,sabotageRuntime.compiled.init(sabotageParams),sabotageInput))
const sabotage={classification:'intentional test-only sabotage',production_is_reference:true,seed:20261025,shortest_tape:[{event:'Interrupt',host:0,t:0,successor:0,log:false}],expected:sabotageActual,sabotaged:{phase:'Completed',bg:0},detected:mismatchOf({phase:'Completed',bg:0},sabotageActual,sabotageCompiled)}
const parity={family:'worker-supervision',method:{seed:20261025,worker_sequences:10000,observed_sequences:1000,lease_sequences:2000,device_sequences:2000,worker_length:'8..32',observed_length:12,resource_length:16,comparison:'each step: pinned Python twin vs interpreted port vs compiled port; canonical fields of active tagged case, plus device effects',scope:'valid Bend event domain; malformed Python-only Start(None) is not a Bend event'},counts,comparison_steps:comparisonSteps,divergences,sabotage,ok:divergences.length===0&&sabotage.detected}
writeFileSync('out/parity.json',JSON.stringify(parity,null,2))
// Snapshot labels are claims, not the oracle. Do not normalize them away to make replay pass.
const traceDivergences=real.filter(x=>x.phase!==x.record.phase).map(x=>({snapshot:x.snapshot,id:x.id,claimed:x.record.phase,replayed:x.phase,classification:'stale or limited oracle',reason:'persisted snapshot label differs from serialized event tape under pinned twin AND port'}))
const read=(name:string)=>JSON.parse(readFileSync('inputs/'+name,'utf8'))
const decisions=readFileSync('inputs/worker-decisions.jsonl','utf8').trim().split('\n').map(x=>JSON.parse(x))
const outcomes=read('worker-resume-outcomes-20261021.json').outcomes
const before=new Map(real.filter(x=>x.snapshot==='worker-supervision-20261021.json').map(x=>[x.id,x]))
const after=new Map(real.filter(x=>x.snapshot==='worker-supervision-20261021-after-apply.json').map(x=>[x.id,x]))
const owner=decisions.map(d=>{
 const record=before.get(d.worker),target=after.get(d.worker),outcome=outcomes.find((o:any)=>o.worker===d.worker)
 if(!record)return {worker:d.worker,action:d.action,classification:'stale or limited oracle',reason:'no before record'}
 const p=wr.encodeParams(record.params),inputValues={event:d.action==='abandon'?'Abandon':d.action==='already integrated'||d.action==='integrated'?'Integrate':'Resume',host:0,t:Math.floor(new Date(d.at).getTime()/1000),successor:0,log:false}
 // Owner routing request is NOT evidence that a successor read a log. Never synthesize log=true.
 const input=wr.encodeInput(inputValues),s=runtimes.get(wr).interpreted.step(p,record.final,input)
 const monitors=watchedLaws.map(l=>watch(wr.machine,runtimes.get(wr).interpreted,l,p,4))
 const violated=monitors.flatMap((w,i)=>{w.start(record.final);return !w.step(record.final,input,s)?[watchedLaws[i].name]:[]})
 const phase=wobs(s).phase
 const expectedProcessPhase=d.action==='abandon'?'Abandoned':d.action==='already integrated'||d.action==='integrated'?'Integrated':'Resumed'
 return {worker:d.worker,action:d.action,input:inputValues,before:record.phase,after_event:phase,refused:eq(wobs(record.final),wobs(s)),expected_disposition_phase:expectedProcessPhase,after_snapshot_phase:target?.record.phase,after_snapshot_event_replay:target?.phase,outcome_state:outcome?.state,outcome_is_process_phase:['abandoned','integrated','resumed'].includes(outcome?.state),watch_violations:violated,classification:phase===expectedProcessPhase?'agreement':'intentional rule difference',reason:phase===expectedProcessPhase?'event is legal':'owner disposition is outside the formal process FSM; resume request lacks log evidence, integration cannot fabricate Finish'}
})
const live=read('live/needs-kevin.json'),ledger=readFileSync('inputs/live/needs-kevin.jsonl','utf8').trim().split('\n').filter(Boolean).map(x=>JSON.parse(x))
const replay={family:'worker-supervision',counts:{records:real.length,steps:real.reduce((n,x)=>n+x.steps,0),watch_evaluations:watchSteps,watch_violations:watchedViolations.length,snapshot_label_divergences:traceDivergences.length,owner_decisions:owner.length,owner_process_refusals:owner.filter(x=>x.refused).length,owner_disposition_gaps:owner.filter(x=>x.classification!=='agreement').length,outcomes:outcomes.length,live_items:live.items.length,live_ledger_rows:ledger.length},snapshots:['worker-supervision-20261021.json','worker-supervision-20261021-after-apply.json'].map(snapshot=>({snapshot,records:real.filter(x=>x.snapshot===snapshot).length,steps:real.filter(x=>x.snapshot===snapshot).reduce((n,x)=>n+x.steps,0)})),divergences:traceDivergences,watch_violations:watchedViolations,owner_decisions:owner,live:{declared_size:live.size,collected:live.items.length,all_items_overdue:live.items.every((x:any)=>x.phase==='Overdue'),owner_decision_overlap:live.items.filter((x:any)=>decisions.some(d=>d.worker===x.worker)).map((x:any)=>({worker:x.worker,phase:x.phase,decision:decisions.find(d=>d.worker===x.worker).action,classification:'stale or limited oracle'})),note:'Live queue is observed classification, not an event tape; no missing events invented. Frozen before fleet execution, never written.'},encoding_gaps:[{fields:['Start.h','Resume.by'],source:'supervise.py:1280-1283',classification:'stale or limited oracle',method:'host recovered as fixed GROOT from worker_traces:964; successor id abstracted as worker enumeration; cannot verify original successor identity from persisted tape'},{fields:['W.id','W.wt'],method:'constant for each rule invocation and omitted from mutable state; heavy/load and exception are modeled exactly; immutable identity preservation not independently proven'}],ok:watchedViolations.length===0&&traceDivergences.length===0&&owner.every(x=>x.classification==='agreement')}
writeFileSync('out/replay.json',JSON.stringify(replay,null,2));console.log(JSON.stringify({parity:parity.ok,counts,comparisonSteps,replay:replay.counts}))
if(!parity.ok)process.exitCode=1
